// Port of rand_core =0.10.1 `src/lib.rs` (lane vendor-rand, plan-m6 D5): the `Rng` / `TryRng` traits Miri's
// `StdRng` (rand 0.10.1 -> chacha20 0.10.0) implements. Doc comments are abridged; see the crate source.
//
// PORT: u32 is `number`, u64 is `bigint` (masked to 64 bits), `&mut [u8]` is a `Uint8Array` (views, so writes
// through `subarray` reach the caller's buffer), `Result<(), E>` is `Result<void, E>`. `Infallible` is `never`.
// `&mut R` / `Box<R>` are `R`, so the `DerefMut` forwarding impls are plain forwarding functions.
// Import this crate only through this file.
import type { Result } from "../../std/result.ts";
import { unreachable } from "../../std/panic.ts";

export * as block from "./block.ts";
export * as utils from "./utils.ts";
export { SeedableRng_provided, type SeedableRng } from "./seedable_rng.ts";
export { UnwrapErr } from "./unwrap_err.ts";
export type { Word } from "./word.ts";

/** `core::convert::Infallible` */
export type Infallible = never;

/// Trait for infallible random number generators
///
/// `Rng` is a sub-trait of [`TryRng`] for infallible generators.
export interface Rng extends TryRng<Infallible> {
  /// Return the next random `u32`.
  // crate: rand_core-0.10.1/src/lib.rs:51 next_u32
  next_u32(): number;

  /// Return the next random `u64`.
  // crate: rand_core-0.10.1/src/lib.rs:54 next_u64
  next_u64(): bigint;

  /// Fill `dest` with random data.
  ///
  /// This method should guarantee that `dest` is entirely filled
  /// with new data, and may panic if this is impossible
  /// (e.g. reading past the end of a file that is being used as the
  /// source of randomness).
  // crate: rand_core-0.10.1/src/lib.rs:62 fill_bytes
  fill_bytes(dst: Uint8Array): void;
}

/** `match r { Ok(x) => x }` on a `Result<T, Infallible>`. */
function into_ok<T>(r: Result<T, Infallible>): T {
  if (r.$ === "Ok") return r._0;
  // PORT: `Infallible` has no values; the match has no `Err` arm upstream.
  unreachable();
}

// impl<R> Rng for R where R: TryRng<Error = Infallible> + ?Sized
// PORT: TS has no blanket impls; an infallible generator's class defines `next_u32`/`next_u64`/`fill_bytes`
// as calls of these (see `rand::rngs::StdRng`).
export const Rng_for_TryRng = {
  // crate: rand_core-0.10.1/src/lib.rs:70 next_u32
  next_u32(self: TryRng<Infallible>): number {
    return into_ok(self.try_next_u32());
  },

  // crate: rand_core-0.10.1/src/lib.rs:77 next_u64
  next_u64(self: TryRng<Infallible>): bigint {
    return into_ok(self.try_next_u64());
  },

  // crate: rand_core-0.10.1/src/lib.rs:84 fill_bytes
  fill_bytes(self: TryRng<Infallible>, dst: Uint8Array): void {
    into_ok(self.try_fill_bytes(dst));
  },
};

/// A marker trait for securely unpredictable infallible RNGs
///
/// This is a convenient trait alias for <code>[TryCryptoRng]<Error = [Infallible]></code>.
/// It is equivalent to the trait sum <code>[Rng] + [TryCryptoRng]</code>.
export interface CryptoRng extends Rng, TryCryptoRng<Infallible> {}

/// Base trait for random number generators and random data sources
///
/// This trait provides a base interface designed to support efficient usage of
/// (`u32`, `u64`) word generators, block generators and random data sources.
/// There is no required relationship between the output of each method or any
/// requirement to use all generated random bits; for example an implementation
/// of [`try_fill_bytes`](Self::try_fill_bytes) may discard some generated bytes
/// to avoid storing a partially used word or block.
// PORT: `type Error` is the type parameter `E`.
export interface TryRng<E = unknown> {
  /// Return the next random `u32`.
  // crate: rand_core-0.10.1/src/lib.rs:196 try_next_u32
  try_next_u32(): Result<number, E>;
  /// Return the next random `u64`.
  // crate: rand_core-0.10.1/src/lib.rs:198 try_next_u64
  try_next_u64(): Result<bigint, E>;
  /// Fill `dst` entirely with random data.
  // crate: rand_core-0.10.1/src/lib.rs:200 try_fill_bytes
  try_fill_bytes(dst: Uint8Array): Result<void, E>;
}

// impl<R: DerefMut> TryRng for R where R::Target: TryRng
// PORT: `self.deref_mut()` is `self` (`&mut R` and `Box<R>` are `R`).
export const TryRng_for_DerefMut = {
  // crate: rand_core-0.10.1/src/lib.rs:210 try_next_u32
  try_next_u32<E>(self: TryRng<E>): Result<number, E> {
    return self.try_next_u32();
  },

  // crate: rand_core-0.10.1/src/lib.rs:215 try_next_u64
  try_next_u64<E>(self: TryRng<E>): Result<bigint, E> {
    return self.try_next_u64();
  },

  // crate: rand_core-0.10.1/src/lib.rs:220 try_fill_bytes
  try_fill_bytes<E>(self: TryRng<E>, dst: Uint8Array): Result<void, E> {
    return self.try_fill_bytes(dst);
  },
};

/// A marker trait over [`TryRng`] for securely unpredictable RNGs
///
/// This marker trait indicates that the implementing generator is intended,
/// when correctly seeded and protected from side-channel attacks such as a
/// leaking of state, to be a cryptographically secure generator. This trait is
/// provided as a tool to aid review of cryptographic code, but does not by
/// itself guarantee suitability for cryptographic applications.
// PORT: a marker trait; erased to the `TryRng` shape.
export interface TryCryptoRng<E = unknown> extends TryRng<E> {}

